mapper.insert:
  INSERT INTO memo
  SET title = #{title}
, content = #{content}

mapper.select:
SELECT id, title, content
FROM memo
ORDER BY id DESC;

SELECT title, content, created_at AS createdAt
FROM memo
WHERE id = #{id}

mapper.update:
  UPDATE memo
  SET title = #{title}
, content = #{content}
  WHERE id = #{id}
